// @freshness: DATA_UPDATED — файл несёт датированную фактуру (цены, правила,
//   погода). Правишь его — бампни DATA_UPDATED в meta.js, иначе подпись
//   «данные проверены на дату X» соврёт. Гейт свежести ищет именно эту метку.
// Расширенные гайды по направлениям — содержательный, проверенный контент сверх
// шаблонного хаба (виза/сезон/бюджет). Заполняется ПОСТРАНИЧНО на реальном ресёрче,
// без выдумок (YMYL). Шаблон [slug].astro рендерит эти секции, ЕСЛИ запись есть;
// у направлений без записи остаётся базовый хаб (graceful).
//
// Поля (все опциональны):
//   intro      — 1–2 фразы: зачем ехать, чем уникально
//   highlights — [{t, d}] что посмотреть и делать (конкретика)
//   getThere   — как добраться (проза)
//   stay       — [{t, d}] где остановиться (варианты)
//   itinerary  — [{t, d}] маршрут по дням
//   practical  — [{t, d}] деньги, связь, пермиты, безопасность
//   faq        — [{q, a}] доп. вопросы (идут и в видимый FAQ, и в schema)
//   authorNote — честный тон: был лично / собрано из источников
//   sources    — [{label, url}] первоисточники (E-E-A-T, не показываем как рекламу)

