    dataNote:
      'Карретера-Аустраль (~1200 км) проходится на арендованном авто с паромными переправами; расстояния большие, инфраструктура редкая — закладывайте запас по времени, топливу и наличным. Конкретные цены сильно зависят от сезона и маршрута.',
    faq: [
      { q: 'Нужна ли виза в Чили россиянам в 2026?', a: 'Нет, виза не нужна: безвизовый въезд для туризма до 90 дней. На границе выдают миграционную карту, которую нужно сохранить до выезда.' },
      { q: 'Как перемещаться по Чилийским фьордам?', a: 'Основной способ — аренда авто на Карретере-Аустраль плюс паромы: часть дороги разорвана фьордами и проходится по воде, билеты на паром бронируют заранее (особенно летом). Между удалёнными регионами быстрее перелетать — Пуэрто-Монтт и Бальмаседа (Койайке).' },
      { q: 'Когда лучше ехать на юг Чили?', a: 'Австральное лето, ноябрь–март: открыты дороги и паромы, максимум светового дня. Зимой (июнь–август) многое закрыто, дожди и короткий день. На крайнем юге погода переменчива в любой сезон.' },
    ],
    authorNote:
      'Лично по Карретере-Аустраль и фьордам Айсена я не ездил — это за пределами моего патагонского маршрута.',
