    getThere:
      'Самолётом Москва — Махачкала, аэропорт Уйташ: около 2 ч 40 мин в пути, прямых рейсов много, цена сильно гуляет по сезону. От аэропорта до города 25 км. Поезд идёт почти двое суток, зато дёшево: плацкарт от ~3 800 ₽, купе от ~4 300 ₽. На машине — около 1 800 км по трассам М4 и Р-217.',
