  // ——— Волна Г2 (черновик 11.09.2026): Египет, Таиланд, Шри-Ланка, ОАЭ. Факты — из статей сайта с журналами сверки
  // (Египет 03–07.09.2026, Таиланд 07.09.2026, ОАЭ 18.08.2026, Шри-Ланка — бесплатная ETA с 25.05.2026), из расписания
