  // ——— Волна Г3 (черновик 11.09.2026): Армения, Кения, Марокко, Филиппины. Факты — из статей сайта о каждой
  // стране (Филиппины — с журналом сверки 27.08.2026 по нормам метеослужбы, визовому порталу и курсам ЦБ).
