    getThere: 'Прямых рейсов из России нет с февраля 2026 года: на Кубе не хватает авиакеросина. «Аэрофлот» в зимнем расписании 2026/27 Кубу не планирует, у Nordwind Гавана в статусе «временно не летаем». Остаются пересадки: рейс Мадрид — Гавана у Air Europa (четыре в неделю, с посадкой на дозаправку в Доминикане) или стыковка в Панаме на рейсы Copa. По острову ездят на такси и прокатных машинах: такси из аэропорта Гаваны в город стоит $30–50, прокат — от $80 в сутки.',
