    getThere: 'Somon Air летает в Душанбе из Домодедова и Жуковского: туда около четырёх часов, обратно — 4 ч 40 мин. Nordwind летает из Шереметьева в Бохтар на юге страны — 4 ч 20 мин. Внутри страны ездят на внедорожниках и общих такси: дорога Душанбе — Хорог занимает целый день, в Фанские горы едут по трассе на Худжанд через Анзобский тоннель.',
